[8496] = { en = "Bandages for the Field", tier = 4,
  t = "Verband voor het slagveld",
  d = "Onze voorraad verband op het slagveld raakt gevaarlijk laag na de recente verliezen die we hebben geleden. Haal een partij eerstehulpmiddelen en lever die af bij Windcaller Proudhorn in Cenarion Hold.",
