[8497] = { en = "Desert Survival Kits", tier = 4,
  t = "Overlevingspakketten voor de woestijn",
  d = "Nu er nieuwe rekruten in Cenarion Hold aankomen, is er een probleem: hoe houden we ze in leven in de woestijn? Uitdroging en veel giftige wezens zijn een serieuze bedreiging voor onervaren vrijwilligers. Verzamel wat nodig is voor een overlevingspakket voor de woestijn en breng het naar Calandrath in Cenarion Hold.",
  o = "Breng 4 Globes of Water, 4 Powerful Anti-Venom en 4 Smoked Desert Dumplings naar Calandrath in de herberg van Cenarion Hold in Silithus. Je moet ook Logistics Task Briefing I meenemen om deze quest te voltooien.",
  g = { {"overlevingspakketten", "survival kits (overlevingspakket)"}, {"rekruten", "recruits (rekruut)"}, {"in leven", "alive"}, {"uitdroging", "dehydration"}, {"giftige", "poisonous (giftig)"}, {"wezens", "creatures (wezen)"}, {"bedreiging", "threat"}, {"onervaren", "inexperienced"}, {"vrijwilligers", "volunteers (vrijwilliger)"}, {"herberg", "inn"} },
