  t = "Gevechtsbevelen van de Twilight's Hammer",
  d = "Onze verkenners melden dat de leiders van de Twilight's Hammer nieuwe gevechtsbevelen geven. De bevelen worden verspreid door Twilight Prophets onder zware bewaking. Onderschep de bevelen en breng ze naar Commander Mar'alith.",
