[8507] = { en = "Field Duty", tier = 4,
  t = "Velddienst",
  d = "Gegroet, $N. Voordat ik je grotere taken in de oorlog geef, moet je eerst je deel van de velddienst doen.$B$BJe vindt de Ironforge Brigade van Captain Blackanvil buiten Hive'Zora.$B$BMeld je bij hem of bij zijn luitenant, Janela Stouthammer, en kom dan terug bij mij. Ik heb dan een moeilijkere opdracht voor je klaar.$B$BO, en doe ons een plezier: blijf uit de buurt van het Orgrimmar Legion. We moeten de twee legers ver uit elkaar houden vanwege wederzijdse vijandigheid.",
  o = "Meld je voor dienst bij de post van de Ironforge Brigade bij Hive'Zora. Houd je Unsigned Field Duty Papers klaar, haal Signed Field Duty Papers bij Captain Blackanvil en ga terug naar Windcaller Kaldon in Cenarion Hold in Silithus.$B$BLet op: als je een lid van de Ironforge Brigade geneest of gunstige spreuken op hem uitspreekt, word je gemarkeerd voor PvP.",
  p = "Je vindt de troepen van Captain Blackanvil buiten Hive'Zora. Praat met zijn luitenant, Janela Stouthammer, als je hem niet kunt vinden.",
  c = "Goed, $N. Ik heb een reeks taken voorbereid waarbij je vaardigheden zo goed mogelijk worden gebruikt.$B$BDankzij de inzet van jou en mensen zoals jij wordt onze vijand binnenkort voorgoed verslagen!$B$BAls je nieuwe instructies voor een missie nodig hebt, ga dan terug naar Captain Blackanvil.",
  g = { {"gegroet", "greetings"}, {"velddienst", "field duty"}, {"luitenant", "lieutenant"}, {"opdracht", "assignment"}, {"doe ons een plezier", "do us a favour"}, {"uit de buurt", "away from"}, {"wederzijdse", "mutual (wederzijds)"}, {"vijandigheid", "animosity, hostility"}, {"gunstige spreuken", "beneficial spells"}, {"gemarkeerd", "flagged, marked (markeren)"}, {"reeks", "series, set"}, {"vaardigheden", "skills (vaardigheid)"}, {"inzet", "effort, dedication"}, {"voorgoed", "once and for all"}, {"verslagen", "defeated (verslaan)"} },
},

