[8519] = { en = "A Pawn on the Eternal Board", tier = 4,
  t = "Een pion op het eeuwige bord",
  d = "Je komt weer tot jezelf en richt je blik. Dan zie je dat er iets beweegt in het kristal. Als je beter kijkt, besef je dat je in het verleden kijkt... een herinnering... lang vergeten.",
  o = "Leer alles wat je kunt over het verleden en spreek dan met Anachronos bij de Caverns of Time in Tanaris.$b",
  c = "Na het verraad van Staghelm verzamelde ik de gebroken stukken van de Scepter of the Shifting Sands en keerde ik hier terug. Ik was vast van plan om de scepter te beschermen tegen wie hem wilde gebruiken om onze wereld kwaad te doen. Zo ontstond de taak van de Dragonflights.$B$BEen scepter die over de vier machtige Aspects verdeeld was, zou bijna onmogelijk te herstellen zijn voor wie bewust chaos zocht... dacht ik. Wat ben ik een dwaas geweest. Zelfs nu word ik opgejaagd door die vervloekte vlucht.",
  e = "De War of the Shifting Sands",
  g = { {"pion", "pawn"}, {"eeuwige", "eternal (eeuwig)"}, {"komt weer tot jezelf", "regain your composure (tot zichzelf komen)"}, {"blik", "gaze, look"}, {"besef", "realise (beseffen)"}, {"herinnering", "memory"}, {"verraad", "betrayal"}, {"vast van plan", "firmly intending"}, {"kwaad te doen", "to do harm"}, {"ontstond", "arose, was born (ontstaan)"}, {"verdeeld", "divided (verdelen)"}, {"bewust", "deliberately, wilfully"}, {"dwaas", "fool"}, {"opgejaagd", "hunted (opjagen)"}, {"vlucht", "(dragon)flight"} },
},

[8534] = { en = "Hive'Zora Scout Report", tier = 4,
  t = "Verkenningsrapport van Hive'Zora",
  d = "We hebben onze beste verkenners diep in de nesten van de silithiden gestuurd om informatie te verzamelen. Scout Azenel houdt de bewegingen van de silithiden bij Hive'Zora al een aantal dagen in de gaten. Zoek haar en haal een geschreven rapport. We moeten zo snel mogelijk iets met die informatie kunnen doen, $N.",
  o = "Zoek contact met Cenarion Scout Azenel in Hive'Zora en breng het Hive'Zora Scout Report naar Windcaller Proudhorn in Cenarion Hold. Je moet ook Tactical Task Briefing VI meenemen om deze quest te voltooien.",
  p = "Je vindt Scout Azenel in Hive'Zora. Schiet op, $N! De tijd dringt.",
  c = "We waarderen je inzet zeer, $N. Ik lees deze verkenningsrapporten meteen. Bekijk gerust je volgende opdracht.",
