[8538] = { en = "The Four Dukes", tier = 4,
  t = "De vier hertogen",
  d = "De banden tussen de Twilight's Hammer en de Abyssal Council blijken belangrijker te zijn dan we hadden verwacht.$B$BWe denken dat de elementaire edelen die bekendstaan als de Abyssal Dukes een van de belangrijkste krachten zijn die de sekteleden van de Twilight's Hammer organiseren. Zoek een manier om de vier Abyssal Dukes naar ons bestaansvlak te lokken en vernietig ze!$B$BOmdat je bij eerdere opdrachten zo toegewijd en bekwaam was, hebben we jou voor deze speciale opdracht gekozen. We zijn er zeker van dat je hierin zult slagen.",
  o = "Zoek een manier om de Duke of Cynders, de Duke of Fathoms, de Duke of Zephyrs en de Duke of Shards op te roepen en te doden, en meld je bij Commander Mar'alith in Cenarion Hold. Je moet ook Tactical Task Briefing V meenemen om deze quest te voltooien.",
  p = "Is je taak al klaar, $N?",
  c = "Je hebt vandaag iets groots bereikt voor onze zaak, $N. Je hebt een paar van onze machtigste vijanden verslagen. Daarvoor prijs ik je zeer.",
