[8737] = { en = "Azure Templar", tier = 4,
  t = "Azure Templar",
  d = "De Twilight's Hammer en de elementaire edelen die zij aanbidden zijn een ernstige bedreiging voor onze operaties in Silithus. Nu we in Ahn'Qiraj tegenover nieuwe vijanden staan, mogen we niet minder alert zijn op onze vijanden daarbuiten.$B$BZoek een manier om een Azure Templar op te roepen en te vernietigen, en meld je bij Bor Wildmane.",
