},

[8738] = { en = "Hive'Regal Scout Report", tier = 4,
  t = "Verkenningsrapport van Hive'Regal",
  d = "We hebben onze beste verkenners diep in de nesten van de silithiden gestuurd om informatie te verzamelen. Scout Landion houdt de bewegingen van de silithiden bij Hive'Regal al een aantal dagen in de gaten. Zoek hem en haal een geschreven rapport. We moeten zo snel mogelijk iets met die informatie kunnen doen, $N.",
  o = "Zoek contact met Cenarion Scout Landion in Hive'Regal en breng het Hive'Regal Scout Report naar Windcaller Proudhorn in Cenarion Hold. Je moet ook Tactical Task Briefing VII meenemen om deze quest te voltooien.",
  p = "Je vindt Scout Landion in Hive'Regal. Schiet op, $N! De tijd dringt.",
  c = "We waarderen je inzet zeer, $N. Ik lees deze verkenningsrapporten meteen. Bekijk gerust je volgende opdracht.",
