[8740] = { en = "Twilight Marauders", tier = 4,
  t = "Rovers van de Twilight's Hammer",
  d = "Groepen bereden sekteleden van de Twilight's Hammer zijn gezien buiten het bereik van onze troepen in Cenarion Hold. Ze vallen onze kleinere patrouilles en karavanen een voor een aan.$B$BZoek en versla de Twilight Marauders en hun leider, een vreselijke krijger met de naam Morna. Meld je bij Windcaller Proudhorn als je de taak hebt voltooid.",
  o = "Dood Twilight Marauder Morna en 2 Twilight Marauders. Meld je bij Windcaller Proudhorn als je taak klaar is. Je moet ook Tactical Task Briefing IX meenemen om deze quest te voltooien.",
  p = "Is je taak al klaar, $N?",
